create table if not exists public.vip_surprise_guide (id integer primary key default 1 check (id=1), title text not null default '돌발 체험 이벤트 안내', body text not null default '', updated_at timestamptz not null default now()); insert into public.vip_surprise_guide(id,title,body) values (1,'돌발 체험 이벤트 안내','그룹채팅에서 예고 없이 진행되는 AI PROCESS 모의 체험 이벤트입니다.\n\n참여 방법\n돌발 이벤트가 시작되면 그룹채팅에 표시되는 이벤트 공지를 확인하고 안내에 따라 참여해 주세요.\n\n진행 확인\n선정된 회원은 AI PROCESS 화면에서 모의 진행 상태와 금액 변화를 확인할 수 있습니다.\n\n완료 안내\n돌발 이벤트 AI PROCESS가 완료되면 그룹채팅에 완료 안내가 표시되며, 일반 회원에게는 1:1 고객센터로 안내 메시지가 발송됩니다.\n\n화면에 표시되는 금액과 수익은 실제 투자 또는 지급 수익이 아닌 모의 체험 수치입니다.') on conflict(id) do nothing; alter table public.vip_surprise_guide enable row level security; create policy "authenticated read guide" on public.vip_surprise_guide for select to authenticated using (true); create or replace function public.admin_update_vip_surprise_guide(p_title text,p_body text) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from public.profiles where id=auth.uid() and role='admin') then raise exception 'ADMIN_ONLY'; end if; update public.vip_surprise_guide set title=left(trim(p_title),100),body=left(p_body,10000),updated_at=now() where id=1; end; $$; grant execute on function public.admin_update_vip_surprise_guide(text,text) to authenticated;